                engine.raise(sce_rust_runtime::EventWithMetadata::platform_error(StaticPayloadRelayEvent::ErrorExecution, "<send> <param name='zoom'> could not be read"));
                // W3C SCXML 5.7.1: the pair is left out; 4.9: the block stops after the send.
                _param_failed = true;
